def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx, ny = x+dx, y+dy
                    if 0 <= nx < h and 0 <= ny < w and (nx,ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx,ny))
                        q.append((nx,ny))
            comps.append((min(x for x,y in cells), min(y for x,y in cells), cells))
    if comps:
        cells = min(comps, key=lambda x: (x[0], x[1]))[2]
        for r, c in cells:
            out[r][c] = 0
    return out
